// src/commands/auto.ts
function createAutoCommand({
  config: config2,
  getSession
}) {
  return {
    name: "auto",
    description: "Enable, disable, or show auto mode status",
    handler: async (context) => {
      const action = context.args.trim().toLowerCase();
      const session = getSession();
      if (!action || action === "on" || action === "enable") {
        config2.autoMode = true;
        await session.log("auto mode enabled.");
        return;
      }
      if (action === "show" || action === "status") {
        await session.log(`auto mode is ${config2.autoMode ? "enabled" : "disabled"}; classifier model: ${formatClassifierModel(config2.classifierModel)}.`);
        return;
      }
      if (action === "off" || action === "disable") {
        config2.autoMode = false;
        await session.log("auto mode disabled.");
        return;
      }
    }
  };
}

// src/errors.ts
function getErrorMessage(error51) {
  return error51 instanceof Error ? error51.message : String(error51);
}

// src/commands/automodel.ts
function createAutomodelCommand({
  config: config2,
  getSession
}) {
  return {
    name: "automodel",
    description: "Set or show the auto mode classifier model",
    handler: async (context) => {
      const arg = context.args.trim();
      const action = arg.toLowerCase();
      const session = getSession();
      if (action === "show" || action === "status") {
        await session.log(`auto mode classifier model: ${formatClassifierModel(config2.classifierModel)}.`);
        return;
      }
      if (action === "default" || action === "reset" || action === "clear") {
        config2.classifierModel = undefined;
        await session.log("auto mode classifier model reset to Copilot default.");
        return;
      }
      if (arg) {
        config2.classifierModel = arg;
        await session.log(`auto mode classifier model set to ${arg}.`);
        return;
      }
      if (!session.capabilities.ui?.elicitation) {
        await session.log("auto mode classifier model unchanged. Use /automodel <model-id> to set it, or /automodel reset to use the Copilot default.");
        return;
      }
      let models;
      try {
        models = await listClassifierModels();
      } catch (error51) {
        await session.log(`auto mode classifier model unchanged. Could not list models: ${getErrorMessage(error51)}`);
        return;
      }
      const modelOptions = [...new Set(models.map((model) => model.id))].sort((a, b) => a.localeCompare(b));
      if (modelOptions.length === 0) {
        await session.log("auto mode classifier model unchanged. No Copilot models are available.");
        return;
      }
      const selectionPrompt = `Select auto mode classifier model (current: ${formatClassifierModel(config2.classifierModel)})`;
      const selectedModel = await session.ui.select(selectionPrompt, modelOptions);
      if (!selectedModel) {
        await session.log("auto mode classifier model unchanged.");
        return;
      }
      config2.classifierModel = selectedModel;
      await session.log(`auto mode classifier model set to ${selectedModel}.`);
    }
  };
}

